#!/usr/bin/env python3
"""Rebuild MEMORY.md from the frontmatter of memory/*.md.

Usage:
  python3 scripts/memory_index.py          # rewrite MEMORY.md
  python3 scripts/memory_index.py --check  # exit 1 if MEMORY.md is out of date
"""
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parent.parent
INDEX = ROOT / "MEMORY.md"
TYPES = {"reference", "lesson", "project", "feedback"}
MAX_LINES = 200
HEADER = (
    "# Memory index\n\n"
    "Generated by `scripts/memory_index.py` from `memory/*.md`. Do not edit by hand.\n"
)


def frontmatter(path):
    lines = path.read_text(encoding="utf-8").splitlines()
    if not lines or lines[0].strip() != "---":
        return None
    meta = {}
    for line in lines[1:]:
        if line.strip() == "---":
            return meta
        key, sep, value = line.partition(":")
        if sep:
            meta[key.strip()] = value.strip().strip("\"'")
    return None


def build():
    entries, problems = [], []
    for path in sorted((ROOT / "memory").glob("*.md")):
        rel = path.relative_to(ROOT).as_posix()
        meta = frontmatter(path)
        if meta is None:
            problems.append(f"{rel}: no frontmatter")
            continue
        missing = [k for k in ("name", "description", "type") if not meta.get(k)]
        if missing:
            problems.append(f"{rel}: frontmatter is missing {', '.join(missing)}")
            continue
        if meta["type"] not in TYPES:
            problems.append(f"{rel}: type '{meta['type']}' is not one of {', '.join(sorted(TYPES))}")
        entries.append(f"- [{meta['name']}]({rel}) — {meta['type']}: {meta['description']}")
    text = HEADER + ("\n" + "\n".join(entries) + "\n" if entries else "")
    if text.count("\n") > MAX_LINES:
        problems.append(f"MEMORY.md has more than {MAX_LINES} lines; merge or remove entries")
    return text, problems


def main():
    text, problems = build()
    for problem in problems:
        print(f"memory_index: {problem}", file=sys.stderr)
    if "--check" in sys.argv[1:]:
        current = INDEX.read_text(encoding="utf-8") if INDEX.exists() else ""
        if current != text:
            print("memory_index: MEMORY.md is out of date; run python3 scripts/memory_index.py", file=sys.stderr)
            return 1
        return 1 if problems else 0
    INDEX.write_text(text, encoding="utf-8")
    return 1 if problems else 0


if __name__ == "__main__":
    sys.exit(main())
